public static byte convertHexDigit(byte b) {
    // Handle invalid input
    if (b < '0' || b > 'f') {
        throw new IllegalArgumentException("Invalid hex digit: " + b);
    }

    // Convert hex digits 0-9 to byte values 0-9
    if (b >= '0' && b <= '9') {
        return (byte) (b - '0');
    }

    // Convert hex digits a-f to byte values 10-15
    if (b >= 'a' && b <= 'f') {
        return (byte) (b - 'a' + 10);
    }

    // Convert hex digits A-F to byte values 10-15
    if (b >= 'A' && b <= 'F') {
        return (byte) (b - 'A' + 10);
    }

    // Default case, return error
    throw new IllegalArgumentException("Invalid hex digit: " + b);
}

