public static String sub(String str, int start, int end) {
  if (str == null || start > end) {
    return null;
  }
  int len = str.length();
  if (start < 0) {
    start = len + start;
  }
  if (end < 0) {
    end = len + end;
  }
  if (start > len || end < 0) {
    return null;
  }
  return str.substring(Math.max(start, 0), Math.min(end, len));
}

