private static Object copyArrayGrow1(final Object array, final Class<?> newArrayComponentType) {
    // Validate input
    if (array == null) {
        if (newArrayComponentType == null) {
            throw new IllegalArgumentException("Cannot create an array with null component type");
        }
        return Array.newInstance(newArrayComponentType, 1);
    } else if (array instanceof Object[] && array.length == 0) {
        throw new IllegalArgumentException("Invalid input array");
    }

    // Get the length and component type of the input array
    int length = array.length;
    Class<?> componentType = array.getClass().getComponentType();

    // Create a new array with a size one greater than the input array
    Object newArray = Array.newInstance(componentType, length + 1);

    // Copy the elements of the input array to the new array
    System.arraycopy(array, 0, newArray, 0, length);

    // Set the last element of the new array to the default value
    newArray[length] = null;

    return newArray;
}

