private String buildContentRange() {
    // Step 1: Validate the input parameters
    if (length <= 0) {
        throw new IllegalArgumentException("Length must be a positive integer");
    }
    if (offset < 0) {
        throw new IllegalArgumentException("Offset must be a non-negative integer");
    }
    // Step 2: Calculate the content range
    int contentRange = offset + length - 1;
    if (contentRange > Integer.MAX_VALUE) {
        throw new ArithmeticException("Content range exceeds maximum value");
    }
    // Step 3: Build the content range string
    return "bytes " + offset + "-" + contentRange + "/" + length;
}

