private TreeNode<T> rotateRight(TreeNode<T> node) {
    // Check if the node is not a leaf node
    if (node.getNumChildren() >= 2) {
        // Find the rightmost child of the left child
        TreeNode<T> rightmostChild = node.getLeftChild().getRightChild();

        // Make the rightmost child the new parent of the node
        rightmostChild.setParent(node);

        // Make the node the left child of the rightmost child
        node.setParent(rightmostChild);

        // Make the left child of the rightmost child the left child of the node
        node.setLeftChild(rightmostChild.getLeftChild());

        // Make the right child of the node the left child of the rightmost child
        rightmostChild.setLeftChild(node.getRightChild());

        // Fix the parent pointers
        node.setRightChild(rightmostChild);
        rightmostChild.setParent(node);

        return rightmostChild;
    } else {
        throw new IllegalArgumentException("Cannot rotate a leaf node");
    }
}

