private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }

    // Set the node's previous node's next to point to the node's next node
    node.prev.next = node.next;

    // Set the node's next node's previous to point to the node's previous node
    node.next.prev = node.prev;

    // Set the node's next and previous to null to remove it from the list
    node.next = null;
    node.prev = null;

    return true;
}

