    // Define the mapping function
    Function<V, V> mapping = (v) -> v;

    // Create a new graph with the same vertices and edges
    Graph<V,E> result = new Graph<>();
    for (V vertex : graph.getVertices()) {
      result.addVertex(vertex);
    }
    for (E edge : graph.getEdges()) {
      result.addEdge(edge);
    }

    // Return the mapping
    return new IsomorphicGraphMapping<>(result, mapping);
