  // Check if either set is null or empty
  if (set1 == null || set1.isEmpty() || set2 == null || set2.isEmpty()) {
    return Collections.emptySet();
  }

  // Create a new set to store the intersection
  Set<V> intersection = new HashSet<>();

  // Iterate over the smaller set and check if each element is in the larger set
  if (set1.size() <= set2.size()) {
    for (V element : set1) {
      if (set2.contains(element)) {
        intersection.add(element);
      }
    }
  } else {
    for (V element : set2) {
      if (set1.contains(element)) {
        intersection.add(element);
      }
    }
  }

  return intersection;
}

