    // Check if the tour is valid and non-empty
    if (tour == null || tour.isEmpty()) {
        throw new IllegalArgumentException("Invalid tour");
    }

    // Create a new graph path
    GraphPath<V,E> path = new GraphPath<V,E>();

    // Iterate over the edges in the tour
    for (E edge : tour) {
        // Check if the edge is valid and belongs to the graph
        if (edge == null || !graph.containsEdge(edge)) {
            throw new IllegalArgumentException("Invalid edge in tour");
        }

        // Add the edge to the path
        path.addEdge(edge);

        // Check if the edge connects the last vertex in the path to a new vertex
        if (path.getLastEdge().getVerteces().contains(edge.getVerteces().get(0))) {
            // Add the new vertex to the path
            path.addVertex(edge.getVerteces().get(1));
        }
    }

    // Return the graph path
    return path;
}

