private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Step 1: Find the bucket with the minimum label
    Set<Integer> minBucket = null;
    for (Set<Integer> bucket : bucketsByLabel) {
        if (bucket.size() > 0) {
            minBucket = bucket;
            break;
        }
    }

    // Step 2: Move all vertices from the minimum bucket to the bucket with label 0
    Set<Integer> emptyExtremalBucket = new HashSet<>();
    for (Integer vertex : minBucket) {
        emptyExtremalBucket.add(vertex);
        labels.set(vertex, 0);
    }
    minBucket.clear();

    // Step 3: Update the labeling accordingly
    for (int i = 0; i < bucketsByLabel.size(); i++) {
        Set<Integer> bucket = bucketsByLabel.get(i);
        if (i != minLabel) {
            for (Integer vertex : bucket) {
                labels.set(vertex, i);
            }
        }
    }
}

