@Override
public MatchResult match(CharSequence uri) {
    if (uri == null) {
        throw new IllegalArgumentException("URI must not be null");
    }
    if (template == null) {
        throw new IllegalStateException("Template must not be null");
    }
    return new MatchResult() {
        private final Map<String, String> variables = new LinkedHashMap<>();
        private final List<String> resolvedVariables = new ArrayList<>();

        @Override
        public boolean matches() {
            // Check if the uri matches the template
            if (!template.apply(uri)) {
                return false;
            }

            // Resolve the variables in the template
            resolveVariables(variables, resolvedVariables);

            // Check if the resolved variables match the expected values
            if (!variables.equals(expectedValues)) {
                return false;
            }

            return true;
        }

        @Override
        public List<String> getResolvedVariables() {
            return resolvedVariables;
        }
    };
}

