@SuppressWarnings("unchecked")
public static void addToClassPath(Vector<URL> cpV, String dir) {
	// Step 1: Check if the directory exists
	File dirFile = new File(dir);
	if (!dirFile.exists()) {
		throw new IllegalArgumentException("Directory does not exist: " + dir);
	}

	// Step 2: Get a list of all the files in the directory
	String[] files = dirFile.list();
	if (files == null) {
		throw new IllegalArgumentException("Cannot list files in directory: " + dir);
	}

	// Step 3: Loop through each file and add it to the classpath vector
	for (String file : files) {
		File entryFile = new File(dir, file);
		if (!entryFile.isFile()) {
			continue;
		}
		URL url = entryFile.toURI().toURL();
		cpV.add(url);
	}
}

