    if (str == null) {
        return null;
    }

    String result = "";
    for (int i = 0; i < str.length(); i++) {
        char ch = str.charAt(i);
        if (ch == '\\') {
            if (i < str.length() - 1) {
                char nextCh = str.charAt(i + 1);
                if (nextCh == 'n') {
                    result += '\n';
                    i++;
                } else if (nextCh == 'r') {
                    result += '\r';
                    i++;
                } else if (nextCh == 't') {
                    result += '\t';
                    i++;
                } else if (nextCh == '\\') {
                    result += '\\';
                    i++;
                }
            } else {
                result += ch;
            }
        } else {
            result += ch;
        }
    }

    return result;
}

