public static Meteor lookup(HttpServletRequest r) {
    if (r == null) {
        throw new IllegalArgumentException("Request parameter cannot be null");
    }
    String meteorId = r.getParameter("meteorId");
    if (meteorId == null || meteorId.isEmpty()) {
        throw new IllegalArgumentException("Meteor ID parameter cannot be null or empty");
    }
    Meteor meteor = null;
    // Search for the meteor in the meteor list
    for (Meteor m : Meteor.meteorList) {
        if (m.getId().equals(meteorId)) {
            meteor = m;
            break;
        }
    }
    // If the meteor is not found, throw an exception
    if (meteor == null) {
        throw new MeteorNotFoundException("The meteor with ID " + meteorId + " was not found");
    }
    return meteor;
}

