public static String deleteAny(String inString, String charsToDelete) {
    // Check if the input string is empty
    if (inString.isEmpty()) {
        return "";
    }

    // Check if the set of characters to delete is empty
    if (charsToDelete.isEmpty()) {
        return inString;
    }

    // Convert the set of characters to delete to a list of characters
    List<Character> charactersToDelete = new ArrayList<>();
    for (char character : charsToDelete.toCharArray()) {
        charactersToDelete.add(character);
    }

    // Loop through the input string and delete any characters that are in the set of characters to delete
    StringBuilder output = new StringBuilder();
    for (char character : inString.toCharArray()) {
        if (!charactersToDelete.contains(character)) {
            output.append(character);
        }
    }

    return output.toString();
}

