public static String trimLeadingCharacter(String str, char leadingCharacter) throws Exception {
    if(str == null || str.isEmpty())
        return null;
    if(leadingCharacter != ' ')
        throw new IllegalArgumentException("Illegal character, only support trimming the character ' '");
    StringBuilder sb = new StringBuilder(str);
    while (sb.charAt(0) == leadingCharacter) {
        sb.deleteCharAt(0);
    }
    while (sb.charAt(sb.length()-1) == leadingCharacter) {
        sb.deleteCharAt(sb.length()-1);
    }
