public static String applyRelativePath(String path, String relativePath) {
    // Check if the relative path is valid
    if (!isValidRelativePath(relativePath)) {
        throw new IllegalArgumentException("The relative path is not valid: " + relativePath);
    }

    // Split the path into its components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Check if the relative path is a file or a folder
    boolean isFile = false;
    if (relativePath.endsWith(".") || relativePath.endsWith("../")) {
        isFile = true;
    }

    // Create a new path by applying the relative path to the path
    StringBuilder newPath = new StringBuilder();
    for (int i = 0; i < pathComponents.length; i++) {
        String component = pathComponents[i];
        if (component.equals(".") || component.equals("..")) {
            continue;
        }
        if (i < relativePathComponents.length) {
            String relativeComponent = relativePathComponents[i];
            if (isFile) {
                newPath.append(component);
            } else {
                int lastIndex = component.lastIndexOf("/");
                if (lastIndex == -1) {
                    newPath.append(component);
                } else {
                    newPath.append(component.substring(0, lastIndex + 1));
                    newPath.append(relativeComponent);
                }
            }
        } else {
            newPath.append(component);
        }
        if (i < pathComponents.length - 1) {
            newPath.append("/");
        }
    }

    // Check if the new path is a file or a folder
    if (isFile) {
        int lastIndex = newPath.lastIndexOf(".");
        if (lastIndex == -1) {
            newPath.append("./");
        } else {
            newPath.append(".");
        }
    }

    return newPath.toString();
}

