public static void selectRow(int row, JTable table, JScrollPane pane) {
    try {
        // Check if the provided row is valid
        if (row < 0 || row >= table.getRowCount()) {
            throw new IllegalArgumentException("Invalid row index: " + row);
        }

        // Check if the provided table and scroll pane are compatible
        if (!table.getParent().equals(pane)) {
            throw new IllegalArgumentException("Table and scroll pane are not compatible");
        }

        // Select the specified row
        table.setRowSelectionInterval(row, row);

        // Scroll the scroll pane to the selected row
        pane.getViewport().setViewPosition(table.getCellRect(row, 0, true).getLocation());

        // Repaint the table to update the selection
        table.repaint();

        // Delay the repaint before scrolling to ensure the table is properly painted
        SwingUtilities.invokeLater(new Runnable() {
            @Override
            public void run() {
                table.repaint();
            }
        });

        // Scroll the scroll pane to the selected row
        pane.getVerticalScrollBar().setValue(row);
    } catch (IllegalArgumentException e) {
        e.printStackTrace();
    }
}

