protected void append(LoggingEvent event) {
  // Handle invalid inputs
  if (event == null) {
    throw new IllegalArgumentException("Logging event cannot be null");
  }

  // Check if the event requires ack
  boolean requiresAck = event.isRequiresAcknowledgment();
  if (requiresAck) {
    // Handle acknowledgment
    String ack = event.getAcknowledgment();
    if (ack == null || ack.isEmpty()) {
      throw new IllegalArgumentException("Acknowledgment is required but not provided");
    }
    // Write the ack message to each connected client
    for (Client client : clients) {
      client.writeMessage(ack);
    }
  }

  // Write the log message to each connected client
  String message = event.getMessage();
  for (Client client : clients) {
    client.writeMessage(message);
  }
}

