public List<TimeRange> buildTimeRanges(long start, long end) {

    // Check if the input time range is valid
    if (start > end) {
        throw new IllegalArgumentException("Start time must be before end time");
    }

    // Initialize the list of time ranges
    List<TimeRange> timeRanges = new ArrayList<>();

    // Calculate the total time range
    long totalTimeRange = end - start;

    // Split the time range into chunks that are smaller than the maximum fetch data duration
    long chunkSize = FETCH_DATA_DURATION;
    for (long i = 0; i < totalTimeRange; i += chunkSize) {
        long chunkStart = start + i;
        long chunkEnd = Math.min(chunkStart + chunkSize - 1, end);
        timeRanges.add(new TimeRange(chunkStart, chunkEnd));
    }

    return timeRanges;
}

