public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null || index < 0 || len < 0) {
        throw new IllegalArgumentException("Invalid input");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            size += 1;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (c <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
    }

    return size;
}

