public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        throw new IllegalArgumentException("str is required");
    }
    if (session == null) {
        throw new IllegalArgumentException("session is required");
    }
    if (lb == null) {
        throw new IllegalArgumentException("lb is required");
    }

    try {
        ByteBuffer byteBuf = ByteBuffer.allocate(8192);
        int written = 0;
        for (int i = 0; i < str.length(); i++) {
            char c = str.charAt(i);
            // Handle surrogate pairs
            if (c >= 0xD800 && c <= 0xDFFF) {
                if (i + 1 < str.length()) {
                    char next = str.charAt(i + 1);
                    if (next >= 0xDC00 && next <= 0xDFFF) {
                        written += writeUTF8(next, session, lb);
                        i++;
                    }
                }
            }
            // Write the byte
            byteBuf.put((byte) c);
            written++;
        }
        lb.put(byteBuf.array(), 0, written);
        return lb;
    } catch (Exception e) {
        throw new RuntimeException("Error writing UTF8 bytes", e);
    }
}

